static int is_prime(long long x) {
    if (x < 2) return 0;
    for (long long d = 2; d <= x / d; d++) {
        if (x % d == 0) return 0;
    }
    return 1;
}
int claim_holds(long long m) {
    long long e = 2 * m;
    for (long long p = 2; p <= e / 2; p++) {
        if (is_prime(p) && is_prime(e - p)) return 1;
    }
    return 0;
}
